import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Build the CUDA extension once
_tsmm_ext = load_inline(
    name="tsmm_ext",
    cpp_sources="",
    cuda_sources="""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <type_traits>
template <typename scalar_t>
__global__ void tsmm_kernel(const scalar_t* __restrict__ A,
                            const scalar_t* __restrict__ B,
                            scalar_t* __restrict__ C,
                            int64_t M, int64_t K, int64_t N) {
    // Tiled GEMM with simple software pipelining (prefetch next tile into registers)
    constexpr int TILE_M = 16;
    constexpr int TILE_N = 64;
    constexpr int TILE_K = 32;
    constexpr int THREAD_TILE_N = 4;
    constexpr int SKEW_B = 8; // shared-memory padding to reduce bank conflicts (keeps 16B row alignment)
    __shared__ scalar_t sA[TILE_M][TILE_K];
    __shared__ scalar_t sB[TILE_K][TILE_N + SKEW_B];
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int row = blockIdx.y * TILE_M + ty;
    int col_base = blockIdx.x * TILE_N + tx * THREAD_TILE_N;
    scalar_t sum[THREAD_TILE_N];
    #pragma unroll
    for (int j = 0; j < THREAD_TILE_N; ++j) sum[j] = static_cast<scalar_t>(0);
    // Preload the first tile (kb = 0) into shared memory
    int64_t kb0 = 0;
    if (row < M) {
        if constexpr (std::is_same<scalar_t, float>::value) {
            bool a_vec_tile = ((K - kb0) >= TILE_K) && ((K & 3LL) == 0);
            if (a_vec_tile) {
                if ((tx & 3) == 0) {
                    const float4* src_a = reinterpret_cast<const float4*>(&A[row * K + (kb0 + tx)]);
                    reinterpret_cast<float4*>(&sA[ty][tx])[0] = src_a[0];
                }
            } else {
                if ((kb0 + tx) < K) {
                    sA[ty][tx] = __ldg(&A[row * K + (kb0 + tx)]);
                } else {
                    sA[ty][tx] = static_cast<scalar_t>(0);
                }
            }
        } else {
            if ((kb0 + tx) < K) {
                sA[ty][tx] = A[row * K + (kb0 + tx)];
                sA[ty][tx] = __ldg(&A[row * K + (kb0 + tx)]);
                sA[ty][tx] = static_cast<scalar_t>(0);
            }
        }
    } else {
        sA[ty][tx] = static_cast<scalar_t>(0);
        sA[ty][tx + 16] = static_cast<scalar_t>(0);
    }
    // Preload second half of A tile (k = kb0 + 16 .. kb0 + 31)
    if (row < M) {
        if constexpr (std::is_same<scalar_t, float>::value) {
            bool a_vec_tile = ((K - kb0) >= TILE_K) && ((K & 3LL) == 0);
            if (a_vec_tile) {
                if ((tx & 3) == 0) {
                    const float4* src_a2 = reinterpret_cast<const float4*>(&A[row * K + (kb0 + 16 + tx)]);
                    reinterpret_cast<float4*>(&sA[ty][tx + 16])[0] = src_a2[0];
                }
            } else {
                if ((kb0 + 16 + tx) < K) {
                    sA[ty][tx + 16] = __ldg(&A[row * K + (kb0 + 16 + tx)]);
                } else {
                    sA[ty][tx + 16] = static_cast<scalar_t>(0);
                }
            }
        } else {
            if ((kb0 + 16 + tx) < K) {
                sA[ty][tx + 16] = __ldg(&A[row * K + (kb0 + 16 + tx)]);
            } else {
                sA[ty][tx + 16] = static_cast<scalar_t>(0);
            }
        }
    } else {
        sA[ty][tx + 16] = static_cast<scalar_t>(0);
    }
    if ((kb0 + ty) < K) {
        if (((N & 3LL) == 0) && (col_base + THREAD_TILE_N - 1) < N) {
            if constexpr (std::is_same<scalar_t, float>::value) {
                const float4* src = reinterpret_cast<const float4*>(&B[(kb0 + ty) * N + col_base]);
                float4 v = src[0];
                reinterpret_cast<float4*>(&sB[ty][tx * THREAD_TILE_N])[0] = v;
            } else {
                #pragma unroll
                for (int j = 0; j < THREAD_TILE_N; ++j) {
                    int col = col_base + j;
                    sB[ty][tx * THREAD_TILE_N + j] = (col < N) ? B[(kb0 + ty) * N + col] : static_cast<scalar_t>(0);
                }
            }
        } else {
            #pragma unroll
            for (int j = 0; j < THREAD_TILE_N; ++j) {
                int col = col_base + j;
                if (col < N) {
                    sB[ty][tx * THREAD_TILE_N + j] = __ldg(&B[(kb0 + ty) * N + col]);
                } else {
                    sB[ty][tx * THREAD_TILE_N + j] = static_cast<scalar_t>(0);
                }
            }
        }
    } else {
        #pragma unroll
        for (int j = 0; j < THREAD_TILE_N; ++j) {
            sB[ty][tx * THREAD_TILE_N + j] = static_cast<scalar_t>(0);
        }
    }
    // Preload second half of B tile rows (k = kb0 + 16 .. kb0 + 31) into sB[16..31]
    if ((kb0 + ty + 16) < K) {
        if (((N & 3LL) == 0) && (col_base + THREAD_TILE_N - 1) < N) {
            if constexpr (std::is_same<scalar_t, float>::value) {
                const float4* src2 = reinterpret_cast<const float4*>(&B[(kb0 + ty + 16) * N + col_base]);
                float4 v2 = src2[0];
                reinterpret_cast<float4*>(&sB[ty + 16][tx * THREAD_TILE_N])[0] = v2;
            } else {
                #pragma unroll
                for (int j = 0; j < THREAD_TILE_N; ++j) {
                    int col = col_base + j;
                    sB[ty + 16][tx * THREAD_TILE_N + j] = (col < N) ? B[(kb0 + ty + 16) * N + col] : static_cast<scalar_t>(0);
                }
            }
        } else {
            #pragma unroll
            for (int j = 0; j < THREAD_TILE_N; ++j) {
                int col = col_base + j;
                if (col < N) {
                    sB[ty + 16][tx * THREAD_TILE_N + j] = __ldg(&B[(kb0 + ty + 16) * N + col]);
                } else {
                    sB[ty + 16][tx * THREAD_TILE_N + j] = static_cast<scalar_t>(0);
                }
            }
        }
    } else {
        #pragma unroll
        for (int j = 0; j < THREAD_TILE_N; ++j) {
            sB[ty + 16][tx * THREAD_TILE_N + j] = static_cast<scalar_t>(0);
        }
    }
    __syncthreads();
    // Software pipelined loop over K tiles (simplified: no register prefetch to reduce registers/occupancy)
    for (int64_t kb = 0; kb < K; kb += TILE_K) {
        // Compute on current tile
        #pragma unroll
        for (int k = 0; k < TILE_K; ++k) {
            scalar_t a = sA[ty][k];
            if constexpr (std::is_same<scalar_t, float>::value) {
                float4 vb = reinterpret_cast<const float4*>(&sB[k][tx * THREAD_TILE_N])[0];
                sum[0] += a * vb.x;
                sum[1] += a * vb.y;
                sum[2] += a * vb.z;
                sum[3] += a * vb.w;
            } else {
                #pragma unroll
                for (int j = 0; j < THREAD_TILE_N; ++j) {
                    sum[j] += a * sB[k][tx * THREAD_TILE_N + j];
                }
            }
        }
        __syncthreads();
        int64_t next_kb = kb + TILE_K;
        if (next_kb < K) {
            // Load next tile directly from global memory into shared memory
            // A next tile first half (k = next_kb .. next_kb + 15)
            if (row < M) {
                if constexpr (std::is_same<scalar_t, float>::value) {
                    bool a_vec_tile_next = ((K - next_kb) >= TILE_K) && ((K & 3LL) == 0);
                    if (a_vec_tile_next) {
                        if ((tx & 3) == 0) {
                            const float4* src_next_a = reinterpret_cast<const float4*>(&A[row * K + (next_kb + tx)]);
                            reinterpret_cast<float4*>(&sA[ty][tx])[0] = src_next_a[0];
                        }
                    } else {
                        if ((next_kb + tx) < K) {
                            sA[ty][tx] = __ldg(&A[row * K + (next_kb + tx)]);
                        } else {
                            sA[ty][tx] = static_cast<scalar_t>(0);
                        }
                    }
                } else {
                    if ((next_kb + tx) < K) {
                        sA[ty][tx] = __ldg(&A[row * K + (next_kb + tx)]);
                    } else {
                        sA[ty][tx] = static_cast<scalar_t>(0);
                    }
                }
            } else {
                sA[ty][tx] = static_cast<scalar_t>(0);
            }
            // A next tile second half (k = next_kb + 16 .. next_kb + 31)
            if (row < M) {
                if constexpr (std::is_same<scalar_t, float>::value) {
                    bool a_vec_tile_next = ((K - next_kb) >= TILE_K) && ((K & 3LL) == 0);
                    if (a_vec_tile_next) {
                        if ((tx & 3) == 0) {
                            const float4* src_next_a2 = reinterpret_cast<const float4*>(&A[row * K + (next_kb + 16 + tx)]);
                            reinterpret_cast<float4*>(&sA[ty][tx + 16])[0] = src_next_a2[0];
                        }
                    } else {
                        if ((next_kb + 16 + tx) < K) {
                            sA[ty][tx + 16] = __ldg(&A[row * K + (next_kb + 16 + tx)]);
                        } else {
                            sA[ty][tx + 16] = static_cast<scalar_t>(0);
                        }
                    }
                } else {
                    if ((next_kb + 16 + tx) < K) {
                        sA[ty][tx + 16] = __ldg(&A[row * K + (next_kb + 16 + tx)]);
                    } else {
                        sA[ty][tx + 16] = static_cast<scalar_t>(0);
                    }
                }
            } else {
                sA[ty][tx + 16] = static_cast<scalar_t>(0);
            }
            // B next tile first half (k = next_kb .. next_kb + 15)
            if ((next_kb + ty) < K) {
                bool vec_ok = (((N & 3LL) == 0) && (col_base + THREAD_TILE_N - 1) < N);
                if (vec_ok) {
                    if constexpr (std::is_same<scalar_t, float>::value) {
                        const float4* src_next = reinterpret_cast<const float4*>(&B[(next_kb + ty) * N + col_base]);
                        reinterpret_cast<float4*>(&sB[ty][tx * THREAD_TILE_N])[0] = src_next[0];
                    } else {
                        #pragma unroll
                        for (int j = 0; j < THREAD_TILE_N; ++j) {
                            int col = col_base + j;
                            sB[ty][tx * THREAD_TILE_N + j] = (col < N) ? B[(next_kb + ty) * N + col] : static_cast<scalar_t>(0);
                        }
                    }
                } else {
                    #pragma unroll
                    for (int j = 0; j < THREAD_TILE_N; ++j) {
                        int col = col_base + j;
                        if (col < N) {
                            sB[ty][tx * THREAD_TILE_N + j] = __ldg(&B[(next_kb + ty) * N + col]);
                        } else {
                            sB[ty][tx * THREAD_TILE_N + j] = static_cast<scalar_t>(0);
                        }
                    }
                }
            } else {
                #pragma unroll
                for (int j = 0; j < THREAD_TILE_N; ++j) {
                    sB[ty][tx * THREAD_TILE_N + j] = static_cast<scalar_t>(0);
                }
            }
            // B next tile second half (k = next_kb + 16 .. next_kb + 31)
            if ((next_kb + ty + 16) < K) {
                bool vec_ok2 = (((N & 3LL) == 0) && (col_base + THREAD_TILE_N - 1) < N);
                if (vec_ok2) {
                    if constexpr (std::is_same<scalar_t, float>::value) {
                        const float4* src_next2 = reinterpret_cast<const float4*>(&B[(next_kb + ty + 16) * N + col_base]);
                        reinterpret_cast<float4*>(&sB[ty + 16][tx * THREAD_TILE_N])[0] = src_next2[0];
                    } else {
                        #pragma unroll
                        for (int j = 0; j < THREAD_TILE_N; ++j) {
                            int col = col_base + j;
                            sB[ty + 16][tx * THREAD_TILE_N + j] = (col < N) ? B[(next_kb + ty + 16) * N + col] : static_cast<scalar_t>(0);
                        }
                    }
                } else {
                    #pragma unroll
                    for (int j = 0; j < THREAD_TILE_N; ++j) {
                        int col = col_base + j;
                        if (col < N) {
                            sB[ty + 16][tx * THREAD_TILE_N + j] = __ldg(&B[(next_kb + ty + 16) * N + col]);
                        } else {
                            sB[ty + 16][tx * THREAD_TILE_N + j] = static_cast<scalar_t>(0);
                        }
                    }
                }
            } else {
                #pragma unroll
                for (int j = 0; j < THREAD_TILE_N; ++j) {
                    sB[ty + 16][tx * THREAD_TILE_N + j] = static_cast<scalar_t>(0);
                }
            }
        }
        __syncthreads();
    }
    // Epilogue stores
    if (row < M) {
        if (((N & 3LL) == 0) && (col_base + THREAD_TILE_N - 1) < N) {
            if constexpr (std::is_same<scalar_t, float>::value) {
                float4 v;
                v.x = sum[0];
                v.y = sum[1];
                v.z = sum[2];
                v.w = sum[3];
                reinterpret_cast<float4*>(&C[row * N + col_base])[0] = v;
            } else {
                #pragma unroll
                for (int j = 0; j < THREAD_TILE_N; ++j) {
                    int col = col_base + j;
                    if (col < N) {
                        C[row * N + col] = sum[j];
                    }
                }
            }
        } else {
            #pragma unroll
            for (int j = 0; j < THREAD_TILE_N; ++j) {
                int col = col_base + j;
                if (col < N) {
                    C[row * N + col] = sum[j];
                }
            }
        }
    }
}
torch::Tensor ts_matmul(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D tensors");
    TORCH_CHECK(A.size(1) == B.size(0),
                "Inner dimensions must match: A is (", A.size(0), ",", A.size(1),
                "), B is (", B.size(0), ",", B.size(1), ")");
    TORCH_CHECK(A.is_contiguous() && B.is_contiguous(),
                "A and B must be contiguous");
    TORCH_CHECK(A.scalar_type() == torch::kFloat32 && B.scalar_type() == torch::kFloat32,
                "Only float32 tensors are supported");
    const int64_t M = A.size(0);
    const int64_t K = A.size(1);
    const int64_t N = B.size(1);
    auto C = torch::empty({M, N}, A.options());
    if (M == 0 || K == 0 || N == 0) {
        return C; // nothing to do
    }
    const dim3 block(16, 16);
    const dim3 grid((N + 64 - 1) / 64,
                    (M + 16 - 1) / 16);
    const float* A_ptr = A.data_ptr<float>();
    const float* B_ptr = B.data_ptr<float>();
    float* C_ptr = C.data_ptr<float>();
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    tsmm_kernel<float><<<grid, block, 0, stream>>>(A_ptr, B_ptr, C_ptr, M, K, N);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return C;
}
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("ts_matmul", &ts_matmul, "Tall/Skinny Matrix Multiplication (CUDA)");
}
